GT_CSS:
.ai-actions .gtranslate_wrapper{display:inline-flex;align-items:center;margin-left:2px;position:relative;z-index:70}
/* seletor de idioma fixo no topo, lado direito */
.gtranslate_wrapper,.ai-actions .gtranslate_wrapper{position:fixed!important;top:10px!important;right:12px!important;left:auto!important;bottom:auto!important;margin:0!important;z-index:99999!important}
.gt_switcher_wrapper{position:fixed!important;top:10px!important;right:12px!important;left:auto!important;bottom:auto!important;margin:0!important;z-index:99999!important}
.ai-actions{margin-right:140px}
/* telemóvel: seletor na mesma linha do cabeçalho (logo | lupa | idioma | menu) */
@media(max-width:900px){
.ai-actions{margin-right:0;gap:2px;flex:none}
.gtranslate_wrapper,.ai-actions .gtranslate_wrapper,.gt_switcher_wrapper{position:static!important;top:auto!important;right:auto!important;left:auto!important;bottom:auto!important;margin:0!important}
.ai-actions .gtranslate_wrapper{display:inline-flex!important;align-items:center;height:28px;margin:0 4px 0 2px!important;padding-left:8px;border-left:1px solid rgba(22,215,245,.55)}
.gt_switcher{width:98px!important}
.gt_switcher .gt_selected a,.gt_switcher .gt_option a{font-size:12px!important;padding:5px 6px!important}
.gt_switcher .gt_selected a img,.gt_switcher .gt_option a img{width:18px!important;height:auto!important}
.gt_switcher{position:static!important}
/* lista de idiomas ancorada ao cabeçalho (nunca sai do ecrã) */
.gt_switcher .gt_option{position:absolute!important;top:100%!important;bottom:auto!important;right:4%!important;left:auto!important;width:170px!important;max-height:min(60vh,320px)!important;overflow-y:auto!important;margin:0!important;z-index:100000!important;box-shadow:0 12px 26px rgba(0,10,30,.45)}
.ai-site-header .ai-brand{gap:8px}
.ai-site-header .ai-brand-mark{width:34px;height:34px}
.ai-site-header .ai-brand-name{font-size:19px}
.ai-site-header .ai-brand-tag{font-size:8px;letter-spacing:.1em}
.ai-site-header .ai-brand-divider{height:26px}
.ai-site-header .ai-search,.ai-site-header .ai-menu-btn{width:36px;height:36px}
}
.ai-actions .gtranslate_wrapper a,.ai-actions .gtranslate_wrapper .gt_selected,.ai-actions .gtranslate_wrapper .gt_selected a{color:#edf5ff!important;text-decoration:none!important}
